取随机装备名称 = function(等级)
	local 随机装备 = 绑定等级物品()
	local 临时等级 = 等级
	local 临时参数 = 取随机数(1, #书铁范围)
	local 临时序列 = 临时参数

	if 临时序列 == 25 then
		临时序列 = 23
	elseif 临时序列 == 24 then
		临时序列 = 22
	elseif 临时序列 == 23 or 临时序列 == 22 then
		临时序列 = 21
	elseif 临时序列 == 21 then
		临时序列 = 20
	elseif 临时序列 == 20 or 临时序列 == 19 then
		临时序列 = 19
	end

	if 临时序列 <= 18 and 临时等级 >= 9 then
		临时等级 = 取随机数(9, 11)
	elseif 临时等级 >= 12 then
		临时等级 = 13
	end

	local 临时类型 = 随机装备[临时序列][临时等级 + 1]

	if type(临时类型) == "table" then
		if 临时参数 == 23 then
			临时类型 = 临时类型[2]
		elseif 临时参数 == 22 then
			临时类型 = 临时类型[1]
		elseif 临时参数 == 20 then
			临时类型 = 临时类型[2]
		elseif 临时参数 == 19 then
			临时类型 = 临时类型[1]
		else
			临时类型 = 临时类型[取随机数(1, 2)]
		end
	end

	return 临时类型
end

取官职任务物品 = function(id)
	local 物品名称 = 玩家数据[id].装备.打造物品[取随机数(1, 23)][取随机数(1, 3)]

	if type(物品名称) == "table" then
		物品名称 = 物品名称[取随机数(1, #物品名称)]
	end

	return 物品名称
end

取武器数据 = function(名称, 级别)
	if 名称 == nil or 级别 == nil then
		return
	end

	local 道具 = 物品类()

	道具:置对象(名称)

	道具.级别限制 = 级别

	return {
		名称 = 名称,
		级别限制 = 级别,
		子类 = 道具.子类
	}
end

