取装备详细说明 = function(名称)
	local aa = 取物品数据(名称)
	local 总类 = aa[2]

	if 总类 == 2 then
		local 分类 = aa[3]
		local 子类 = aa[4]
		local 级别 = aa[5]
		local 性别 = aa[6]
		种类 = 装备种类[分类]

		if 种类 == "武器" then
			种类 = 武器种类[子类]
		end

		if 性别 == "男" or 性别 == "女" then
			种类 = 性别 .. 种类
		end

		if 级别 ~= nil then
			级别 = 级别 .. "级"
		end

		if 通灵装备1[名称] ~= nil then
			种类 = "通灵装备"
			级别 = 个位数字转汉字(通灵装备1[名称]) .. "级"
		end

		return 名称 .. "#R(" .. (级别 or "0级") .. 种类 .. ")#W"
	end

	return 名称
end

