复制物品 = function(物品)
	local 道具数据 = 物品类()

	道具数据:置对象(物品.名称)

	道具数据.总类 = 物品.总类
	道具数据.分类 = 物品.分类
	道具数据.子类 = 物品.子类

	if 物品.伤害 ~= nil then
		道具数据.伤害 = 物品.伤害
	end

	if 物品.气血 ~= nil then
		道具数据.气血 = 物品.气血
	end

	if 物品.魔法 ~= nil then
		道具数据.魔法 = 物品.魔法
	end

	if 物品.愤怒 ~= nil then
		道具数据.愤怒 = 物品.愤怒
	end

	if 物品.体力 ~= nil then
		道具数据.体力 = 物品.体力
	end

	if 物品.活力 ~= nil then
		道具数据.活力 = 物品.活力
	end

	if 物品.命中 ~= nil then
		道具数据.命中 = 物品.命中
	end

	if 物品.伤害 ~= nil then
		道具数据.伤害 = 物品.伤害
	end

	if 物品.防御 ~= nil then
		道具数据.防御 = 物品.防御
	end

	if 物品.速度 ~= nil then
		道具数据.速度 = 物品.速度
	end

	if 物品.躲避 ~= nil then
		道具数据.躲避 = 物品.躲避
	end

	if 物品.灵力 ~= nil then
		道具数据.灵力 = 物品.灵力
	end

	if 物品.体质 ~= nil then
		道具数据.体质 = 物品.体质
	end

	if 物品.魔力 ~= nil then
		道具数据.魔力 = 物品.魔力
	end

	if 物品.力量 ~= nil then
		道具数据.力量 = 物品.力量
	end

	if 物品.耐力 ~= nil then
		道具数据.耐力 = 物品.耐力
	end

	if 物品.敏捷 ~= nil then
		道具数据.敏捷 = 物品.敏捷
	end

	if 物品.品质 ~= nil then
		道具数据.品质 = 物品.品质
	end

	if 物品.附带技能 ~= nil then
		道具数据.附带技能 = 物品.附带技能
	end

	if 物品.镶嵌四相 ~= nil then
		道具数据.镶嵌四相 = 物品.镶嵌四相
	end

	if 物品.锻炼等级 ~= nil then
		道具数据.锻炼等级 = 物品.锻炼等级
	end

	if 物品.镶嵌宝石 ~= nil then
		道具数据.镶嵌宝石 = 物品.镶嵌宝石
	end

	if 物品.级别限制 ~= nil then
		道具数据.级别限制 = 物品.级别限制
	end

	if 物品.特效 ~= nil then
		道具数据.特效 = 物品.特效
	end

	if 物品.特技 ~= nil then
		道具数据.特技 = 物品.特技
	end

	if 物品.价格 ~= nil then
		道具数据.价格 = 物品.价格
	end

	if 物品.五行 ~= nil then
		道具数据.五行 = 物品.五行
	end

	if 物品.数量 ~= nil and 物品.可叠加 then
		道具数据.数量 = 物品.数量
	end

	if 物品.制造者 ~= nil then
		道具数据.制造者 = 物品.制造者
	end

	return 道具数据
end
